def remove_Occ(s, ch):
    first = s.find(ch)
    if first == -1:
        return s  # character not found, return original string
    last = s.rfind(ch)
    if first == last:
        # only one occurrence
        return s[:first] + s[first+1:]
    else:
        # remove last first to avoid index shift issues
        return s[:first] + s[first+1:last] + s[last+1:]

