def solution(a, b, n):
    g = math.gcd(a, b)
    if n % g != 0:
        return 'No solution'

    # Extended Euclidean Algorithm
    def egcd(a, b):
        if b == 0:
            return (a, 1, 0)
        else:
            g, x1, y1 = egcd(b, a % b)
            return (g, y1, x1 - (a // b) * y1)

    g, x0, y0 = egcd(a, b)
    # Scale to get a solution for ax + by = n
    x0 *= n // g
    y0 *= n // g

    # General solution:
    # x = x0 + (b/g)*t
    # y = y0 - (a/g)*t
    step_x = b // g
    step_y = a // g

    if step_x != 0:
        # Find smallest t such that x0 + step_x * t >= 0
        t = math.ceil(-x0 / step_x)
        x = x0 + step_x * t
        y = y0 - step_y * t
    else:
