def is_valid_parenthese(s: str) -> bool:
    stack = []
    mapping = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in mapping.values():  # opening brackets
            stack.append(char)
        elif char in mapping:  # closing brackets
            if not stack or stack[-1] != mapping[char]:
                return False
            stack.pop()
        else:
            # If the string contains other characters, we could ignore or return False.
            # Here, we assume only parentheses characters are present.
            return False

    return len(stack) == 0

