def sort_on_occurence(lst):
    from collections import OrderedDict

    groups = OrderedDict()
    for key, val in lst:
        if key not in groups:
            groups[key] = []
        groups[key].append(val)

    result = []
    for key, vals in groups.items():
        result.append((key, *vals, len(vals)))

    # Sort by count (last element) descending, stable sort keeps original order for ties
    result.sort(key=lambda x: x[-1], reverse=True)

    return result

