def find_Divisor(a, b):
    from collections import defaultdict
    freq = defaultdict(int)

    for n in range(a, b + 1):
        for d in range(2, int(n**0.5) + 1):
            if n % d == 0:
                freq[d] += 1
                if d != n // d:
                    freq[n // d] += 1
        if n >= 2:
            freq[n] += 1  # n is a divisor of itself

