def zigzag(n, k):
    # Entringer number E(n, k)
    # Base cases
    if n == 0 and k == 0:
        return 1
    if n == 0 or k < 0 or k > n:
        return 0

    # Create DP table
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1

