def ncr_modp(n, r, p):
    if r < 0 or r > n:
        return 0
    r = min(r, n - r)  # take advantage of symmetry
    result = 1
    for i in range(1, r + 1):
        result = result * (n - r + i) // i
    return result % p

def find_Parity(num):
