def k_smallest_pairs(nums1, nums2, k):
    if not nums1 or not nums2 or k <= 0:
        return []

    # Generate all pairs with their sums
    pairs = []
    for i, a in enumerate(nums1):
        for j, b in enumerate(nums2):
            pairs.append((a + b, i, j, [a, b]))

    # Sort by sum, then by index in first array, then by index in second array
    pairs.sort(key=lambda x: (x[0], x[1], x[2]))

    # Return the first k pairs
    return [pair[3] for pair in pairs[:k]]

