def cal_sum(n):
    if n == 0:
        return 3
    elif n == 1:
        return 3  # 3 + 0
    elif n == 2:
        return 5  # 3 + 0 + 2

    # Initialize first three Perrin numbers
    p0, p1, p2 = 3, 0, 2
    total = p0 + p1 + p2  # sum for n=2

    for i in range(3, n + 1):
        p_next = p1 + p0  # P(i) = P(i-2) + P(i-3)
        total += p_next
        # shift variables
        p0, p1, p2 = p1, p2, p_next

    return total

