def count_Substrings(s, n):
    # n is the length of the string (given in the problem)
    # We'll use prefix sums for efficiency
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i+1] = prefix[i] + int(s[i])

    count = 0
    for length in range(1, n+1):
        for start in range(n - length + 1):
            end = start + length
            digit_sum = prefix[end] - prefix[start]
            if digit_sum == length:
                count += 1
    return count

